In the next section we define odd and even online semimeasures. 
We fix such semimeasures $\operatorname{P_{\textnormal{ev}}}$ and $\operatorname{P_{\textnormal{odd}}}$ that can be computed with $s + O(|x|)$ space and satisfy 
\begin{align*}
  \operatorname{C}^s(x) \ge \log \frac 1 {\operatorname{P_{\textnormal{ev}}}(x)} + \log \frac 1 {\operatorname{P_{\textnormal{odd}}}(x)}. 
\end{align*}
Let $k = \operatorname{C}^s(x)$. 
We prove a space-bounded version of the online coding theorem from~\cite{onlineComplexity}. This implies
\begin{align*}
  \operatorname{C}_\textnormal{odd}^s(x) &\le \log \frac 1 {\operatorname{P_{\textnormal{odd}}}(x)} + O(\operatorname{C}^s(s,|x|,k)) \\
  \operatorname{C}_\textnormal{ev}^s(x) &\le \log \frac 1 {\operatorname{P_{\textnormal{ev}}}(x)} + O(\operatorname{C}^s(s,|x|,k)). 
\end{align*}
The theorem follows by combining the 3 inequalities.

Let $P$ be a mapping from strings to the real interval $[0,1]$. 
  \begin{itemize}
    \par 
      $P$ is a {\em semimeasure} if for all~$x$, 
      \[
	P(x) \ge P(x0) + P(x1).
      \]
    \par 
      $P$ is an {\em even semimeasure} if for all~$x$, 
      \begin{eqnarray*}
	\textnormal{if $|x|$ is even } & \Rightarrow & P(x) = P(x0) = P(x1) \\
	  \textnormal{if $|x|$ is odd }  & \Rightarrow & P(x) \ge P(x0) + P(x1). 
      \end{eqnarray*}
    \par 
      $P$ is an {\em odd semimeasure} if for all~$x$, 
      \begin{eqnarray*}
	\textnormal{if $|x|$ is odd } & \Rightarrow & P(x) = P(x0) = P(x1) \\
	  \textnormal{if $|x|$ is even }  & \Rightarrow & P(x) \ge P(x0) + P(x1). 
      \end{eqnarray*}
  \end{itemize}
